('127.109.d.11.C',4,'A 200-ampere service at 240 volts can supply how many volt-amperes?','["4,800", "48,000", "480,000", "2,400"]'::jsonb,1,'200 x 240 = 48,000.','original'),
('127.109.d.11.D',3,'Wiring methods for a home include nonmetallic sheathed cable and:','["String", "Tape", "Conduit systems", "Rope"]'::jsonb,2,'Methods vary.','original'),
